cards = [
    "As a clerk, I want to flag difficult patients, so that staff handle visits calmly.",
    "As a manager, I want a report.",
    "As a manager, I want a report, so that decisions get better.",
    "The system must use MongoDB for speed.",
]

def check_story(story):
    if not story.startswith("As a "):
        return "missing role"
    if ", I want " not in story:
        return "missing capability"
    if ", so that " not in story:
        return "missing goal"
    return "OK"

for i, story in enumerate(cards, 1):
    print("story%d: %s" % (i, check_story(story)))

SCENARIOS = [
    {'actor': 'front-desk clerk', 'action': 'check in an arriving patient'},
    {'actor': 'impostor', 'action': 'reset another users password', 'stride': 'Spoofing'},
    {'actor': 'clinician', 'action': 'open the day visit list'},
    {'actor': 'ex-employee', 'action': 'read records with revoked rights', 'stride': 'Elevation of privilege'},
]
MISUSERS = {'impostor', 'ex-employee', 'stranger'}

def classify(sc):
    return 'abuse' if sc['actor'] in MISUSERS else 'normal'

normal = 0
abuse = 0
for i, sc in enumerate(SCENARIOS, 1):
    kind = classify(sc)
    if kind == 'abuse':
        abuse += 1
        print('case %d abuse (%s)' % (i, sc['stride']))
    else:
        normal += 1
        print('case %d normal' % i)
print('normal: %d abuse: %d' % (normal, abuse))
